"""Generate TypeScript, JSON Schema and frozen UI fixtures from Python contracts.

Run from the repository root with .venv/bin/python scripts/export_contract.py.
--check compares generated bytes without changing tracked files.
"""
import argparse
import json
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from api import schemas
from api.scenarios import ScenarioStore

MODELS=[getattr(schemas,n) for n in dir(schemas) if isinstance(getattr(schemas,n),type)
        and issubclass(getattr(schemas,n),schemas.Model) and n!='Model']

def ts(node):
    if '$ref' in node:
        return node['$ref'].split('/')[-1]
    if 'const' in node:
        return json.dumps(node['const'])
    if 'enum' in node:
        return ' | '.join(json.dumps(v) for v in node['enum'])
    if 'anyOf' in node:
        return ' | '.join(ts(v) for v in node['anyOf'])
    kind=node.get('type')
    if kind=='array':
        return f'Array<{ts(node["items"])}>'
    if kind=='object':
        required=node.get('required',[])
        return '{\n'+''.join(f'  {json.dumps(k)}{"" if k in required else "?"}: {ts(v)};\n'
                             for k,v in node.get('properties',{}).items())+'}'
    return {'string':'string','number':'number','integer':'number','boolean':'boolean','null':'null'}.get(kind,'unknown')

def outputs():
    definitions={}
    for model in MODELS:
        schema=model.model_json_schema(mode='serialization')
        definitions.update(schema.pop('$defs',{}))
        definitions[model.__name__]=schema
    header='// Generated by scripts/export_contract.py from api/schemas.py. Do not edit.\n'
    types=header+'\n\n'.join(f'export type {name} = {ts(definition)};' for name,definition in sorted(definitions.items()))+'\n'
    store=ScenarioStore()
    run=store.runs['multi_fault']
    run.run_id='RUN-FIXTURE-001'
    run.snapshot=store._build(run)
    result=store.apply('multi_fault',schemas.Action(action_id='fixture-outage',expected_revision=1,action='advance'))
    snapshot=result.snapshot.model_dump(mode='json')
    customer=result.customers['P-DEMO-001'].model_dump(mode='json')
    for body in [snapshot,customer]:body['timestamp_utc']='2026-10-24T20:00:00Z'
    dump=lambda v:json.dumps(v,indent=2,ensure_ascii=False)+'\n'
    return {'contracts/types.ts':types,
            'contracts/schema.json':dump({'$schema':'https://json-schema.org/draft/2020-12/schema','$defs':definitions}),
            'contracts/sample_snapshot.json':dump(snapshot),
            'contracts/sample_customer_snapshot.json':dump(customer)}

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    stale=[]
    for name,content in outputs().items():
        path=ROOT/name
        if args.check:
            if not path.exists() or path.read_text()!=content:stale.append(name)
        else:
            path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content)
    if stale:
        print('Stale generated contracts: '+', '.join(stale));sys.exit(1)
    print('Contracts match Python schemas.' if args.check else 'Generated contracts and fixtures.')
